/* set the configured scheduling policy (if possible) */
static rsRetVal setSchedParams(modConfData_t *modConf) {
    DEFiRet;

#ifdef HAVE_PTHREAD_SETSCHEDPARAM
    int err;
    struct sched_param sparam;

    if (modConf->iSchedPrio == SCHED_PRIO_UNSET) FINALIZE;

    memset(&sparam, 0, sizeof sparam);
    sparam.sched_priority = modConf->iSchedPrio;
    dbgprintf("imudp trying to set sched policy to '%s', prio %d\n", modConf->pszSchedPolicy, modConf->iSchedPrio);
    err = pthread_setschedparam(pthread_self(), modConf->iSchedPolicy, &sparam);
    if (err != 0) {
        LogError(err, NO_ERRCODE, "imudp: pthread_setschedparam() failed - ignoring");
    }
finalize_it:
#endif

    RETiRet;
}


